from __future__ import annotations
import csv, hashlib, json
from collections import defaultdict
from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from pathlib import Path

@dataclass
class FileRecord:
    path: str
    size: int
    sha256: str
    modified_utc: str
    accessed_utc: str
    status_changed_utc: str

def utc_iso(ts: float) -> str:
    return datetime.fromtimestamp(ts, tz=timezone.utc).isoformat()

def sha256_file(path: Path, chunk_size: int = 1024*1024) -> str:
    h=hashlib.sha256()
    with path.open('rb') as f:
        while True:
            b=f.read(chunk_size)
            if not b: break
            h.update(b)
    return h.hexdigest()

def collect_records(root: Path):
    out=[]
    for p in sorted(root.rglob('*')):
        if p.is_symlink() or not p.is_file(): continue
        st=p.stat()
        out.append(FileRecord(str(p.relative_to(root)),st.st_size,sha256_file(p),utc_iso(st.st_mtime),utc_iso(st.st_atime),utc_iso(st.st_ctime)))
    return out

def duplicate_groups(records):
    groups=defaultdict(list)
    for r in records: groups[r.sha256].append(r.path)
    return {k:v for k,v in groups.items() if len(v)>1}

def write_csv(records,path):
    fields=['path','size','sha256','modified_utc','accessed_utc','status_changed_utc']
    with path.open('w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=fields); w.writeheader()
        for r in records: w.writerow(asdict(r))

def write_json(records,path):
    path.write_text(json.dumps({'file_count':len(records),'records':[asdict(r) for r in records]},indent=2),encoding='utf-8')

def write_duplicates(records,path):
    path.write_text(json.dumps({'duplicate_groups':duplicate_groups(records)},indent=2),encoding='utf-8')

