import tempfile,unittest
from pathlib import Path
from forensic_core import collect_records,duplicate_groups
class TestCore(unittest.TestCase):
 def test_duplicates(self):
  with tempfile.TemporaryDirectory() as td:
   r=Path(td); (r/'a').write_text('same'); (r/'b').write_text('same'); (r/'c').write_text('different')
   rs=collect_records(r); self.assertEqual(len(rs),3); self.assertEqual(sorted(next(iter(duplicate_groups(rs).values()))),['a','b'])
 def test_symlink(self):
  with tempfile.TemporaryDirectory() as td:
   r=Path(td); t=r/'target'; t.write_text('x'); (r/'link').symlink_to(t); self.assertEqual([x.path for x in collect_records(r)],['target'])
if __name__=='__main__': unittest.main()
